census_source:
[Module load: #json];
let input := "duration_ms";
[4 timesRepeat: [| [input jsonUnescape]]];
[System gc]; [System autoGc: false];
[Vtable dispatchCountsBegin];
let answer := [input jsonUnescape];
let counts := [[Execution bytesResultOf: Vtable selector: #dispatchCountsEnd] asString];
[System writeFile: "/tmp/birnam-cpu-20261011/unescape-counts.tsv" contents: counts];
[System writeFile: "/tmp/birnam-cpu-20261011/unescape-edges.tsv" contents: [[Execution bytesResultOf: Vtable selector: #dispatchEdges] asString]];
[System writeFile: "/tmp/birnam-cpu-20261011/unescape-subtrees.tsv" contents: [[Execution bytesResultOf: Vtable selector: #dispatchSubtrees] asString]];
[System writeFile: "/tmp/birnam-cpu-20261011/unescape-trace.tsv" contents: [[Execution bytesResultOf: Vtable selector: #dispatchTrace] asString]];
[System println: answer]
